// EXPERIMENT linexp-1/b580-reuse (generated by exp/linexp-1/b580-reuse/tools/gen_exp.py): 8da4w kernels without
// fp32 totals in registers across the K loop (glsl/sarc_dev/sarc_exp_linear_dq8ca_coopmat_zpg.yaml). Candidate
// rows: never chosen by a table; a row fits only while ET_VK_SARC_EXP starts with "exp-", and is then selected
// by name with ET_VK_SARC_DQ8CA_VARIANT (which needs ET_VK_SARC_UNVERIFIED=1 on this card). The `_i32_` rows
// are timing-only ablations that are INCORRECT BY CONSTRUCTION for more than one quantization group.

#include <executorch/backends/vulkan/runtime/graph/ops/impl/sarc/Select.h>

#include <cstdlib>
#include <cstring>

namespace vkcompute {
namespace sarc {
namespace {

bool exp_requested(const ShapeInfo&) {
  const char* e = std::getenv("ET_VK_SARC_EXP");
  return e != nullptr && std::strncmp(e, "exp-", 4) == 0;
}

const Row kExpLinearCandidates[] = {
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_sh_t64x128k32g82s16m8",
     {64, 128, 32, 8, 2, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_sh_t64x128k32g42s16m8",
     {64, 128, 32, 4, 2, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_sh_t64x128k32g22s16m8pm",
     {64, 128, 32, 2, 2, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_sh_t64x128k32g21s16m8pm",
     {64, 128, 32, 2, 1, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_sh_t64x128k32g11s16m8pm",
     {64, 128, 32, 1, 1, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_i32_t128x128k64g84s16m8",
     {128, 128, 64, 8, 4, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_i32_t128x128k64g44s16m8",
     {128, 128, 64, 4, 4, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_i32_t128x128k64g24s16m8",
     {128, 128, 64, 2, 4, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_i32_t128x128k64g22s16m8pm",
     {128, 128, 64, 2, 2, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
    {"", nullptr, Op::kDq8caLinear,
     "sarc_exp_linear_dq8ca_coopmat_zpg_i32_t128x128k64g12s16m8pm",
     {128, 128, 64, 1, 2, 16, 8, false}, kTex3dTex2d, exp_requested, Status::kUnverified},
};

struct Registrar {
  Registrar() {
    register_candidates(
        kExpLinearCandidates,
        sizeof(kExpLinearCandidates) / sizeof(kExpLinearCandidates[0]));
  }
} registrar;

} // namespace
} // namespace sarc
} // namespace vkcompute
